import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.Ki30n65y.js";const k=JSON.parse('{"title":"Install with Docker","description":"","frontmatter":{},"headers":[],"relativePath":"install/docker.md","filePath":"install/docker.md"}'),o={name:"install/docker.md"};function d(n,e,r,h,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="install-with-docker" tabindex="-1">Install with Docker <a class="header-anchor" href="#install-with-docker" aria-label="Permalink to &quot;Install with Docker&quot;">​</a></h1><p>This guide installs DepGate for production use with Docker Compose. DepGate runs as a single container that serves the web interface, the REST API and every package registry on one address. Two setups are available, and both run the published image only; nothing is built on the server.</p><table tabindex="0"><thead><tr><th>Setup</th><th>Folder</th><th>PostgreSQL and Redis</th></tr></thead><tbody><tr><td><strong>All-in-one</strong></td><td><code>deploy/all-in-one/</code></td><td>Included in the same Compose file, on the same host. Not reachable from the network.</td></tr><tr><td><strong>App only</strong></td><td><code>deploy/app-only/</code></td><td>Your own servers: another machine, or a managed service.</td></tr></tbody></table><p>For a cluster with several replicas, see <a href="./kubernetes">Install on Kubernetes</a>. Before you start, check the <a href="./requirements">Requirements</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><ol><li>Get the <code>deploy/</code> folder onto the host.</li><li>Choose a setup and create <code>.env</code>.</li><li>Add a TLS certificate, or put DepGate behind your own TLS proxy.</li><li>Start DepGate and sign in.</li></ol><p>Each setup folder has the same files:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>docker-compose.yml</code></td><td>Runs DepGate from its image (and, in all-in-one, PostgreSQL and Redis). It never builds anything.</td></tr><tr><td><code>.env.example</code></td><td>Every setting, with explanations. <code>1-configure.sh</code> turns it into <code>.env</code>.</td></tr><tr><td><code>1-configure.sh</code></td><td>Writes <code>.env</code> with generated secrets.</td></tr><tr><td><code>2-generate-cert.sh</code></td><td>Issues an HTTPS certificate from a local CA, when you have no company certificate.</td></tr><tr><td><code>3-run.sh</code></td><td>Starts DepGate, waits until it is healthy, and checks what it serves. Also <code>--stop</code> and <code>--logs</code>.</td></tr><tr><td><code>quickstart.sh</code></td><td>The three steps with defaults.</td></tr><tr><td><code>certs/</code></td><td>Your certificate files: <code>tls.crt</code>, <code>tls.key</code> and <code>ca.crt</code>.</td></tr></tbody></table><p>The scripts use <code>deploy/common/</code>, so copy the whole <code>deploy/</code> folder, not one subfolder.</p><h2 id="step-1-get-the-deploy-folder-and-the-image" tabindex="-1">Step 1: Get the deploy folder and the image <a class="header-anchor" href="#step-1-get-the-deploy-folder-and-the-image" aria-label="Permalink to &quot;Step 1: Get the deploy folder and the image&quot;">​</a></h2><p>The <code>deploy/</code> folder of the repository holds the compose files and scripts. Clone the repository on the host, or copy that folder to it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/secmods/depgate.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depgate/deploy</span></span></code></pre></div><p>The image <code>secmods/depgate:&lt;version&gt;</code> is pulled from Docker Hub when DepGate first starts; no sign-in is needed. The same image is on GitHub as <code>ghcr.io/secmods/depgate:&lt;version&gt;</code>: set <code>DEPGATE_IMAGE=ghcr.io/secmods/depgate</code> in <code>.env</code> to pull it from there. Docker Hub allows a limited number of pulls per hour from one address without signing in; hosts that pull often, or many hosts behind one address, can use GitHub or <code>docker login</code>. With an internal registry mirror, set <code>DEPGATE_IMAGE</code> in <code>.env</code> to the mirror&#39;s name (and <code>docker login</code> once if it needs sign-in). To build the image yourself, see <a href="./build-from-source#build-the-production-image">Build from source</a>.</p><h2 id="step-2-choose-a-setup-and-configure" tabindex="-1">Step 2: Choose a setup and configure <a class="header-anchor" href="#step-2-choose-a-setup-and-configure" aria-label="Permalink to &quot;Step 2: Choose a setup and configure&quot;">​</a></h2><h3 id="all-in-one" tabindex="-1">All-in-one <a class="header-anchor" href="#all-in-one" aria-label="Permalink to &quot;All-in-one&quot;">​</a></h3><p>PostgreSQL 17 and Redis 7 run in the same Compose file, with generated passwords, Redis set to <code>noeviction</code> with persistence, and no published ports. Use it for a team or a pilot on one server.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all-in-one</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GATEWAY_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://depgate.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADMIN_EMAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">security-team@example.com</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./1-configure.sh</span></span></code></pre></div><p>The script writes <code>.env</code> with a random <code>JWT_SECRET</code>, admin password, <code>DB_PASSWORD</code> and <code>REDIS_PASSWORD</code>, and protects it with <code>chmod 600</code>. The database connection is fixed in the Compose file; <code>.env</code> holds only the passwords.</p><h3 id="app-only" tabindex="-1">App only <a class="header-anchor" href="#app-only" aria-label="Permalink to &quot;App only&quot;">​</a></h3><p>DepGate connects to PostgreSQL and Redis you run elsewhere. Prepare them first:</p><ol><li><p>Create an empty PostgreSQL database and a user that owns it. DepGate creates the tables on first start, but not the database or the user. As a PostgreSQL superuser:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> depgate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LOGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- DB_USER and DB_PASSWORD</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> depgate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OWNER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> depgate;        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- DB_NAME</span></span></code></pre></div><p>Use a new database, not one that already has tables (such as a development database): DepGate refuses to start on it. Allow 25 connections per DepGate instance. See <a href="./requirements#database">Requirements</a>.</p></li><li><p>Make sure Redis uses <code>maxmemory-policy noeviction</code> and AOF persistence, as one endpoint. Redis Cluster mode is not supported.</p></li></ol><p>Then pass the connection details to the script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-only</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pg.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DB_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DB_SSL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDIS_URL=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;rediss://:…@redis.example.com:6380&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GATEWAY_URL=https://depgate.example.com </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ADMIN_EMAIL=security-team@example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./1-configure.sh</span></span></code></pre></div><p>For servers on the same host outside Docker, use <code>DB_HOST=host.docker.internal</code>.</p><h3 id="what-env-holds" tabindex="-1">What <code>.env</code> holds <a class="header-anchor" href="#what-env-holds" aria-label="Permalink to &quot;What \`.env\` holds&quot;">​</a></h3><p>The settings people usually change:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><code>DEPGATE_IMAGE</code>, <code>DEPGATE_VERSION</code></td><td><code>secmods/depgate</code>, <code>1.0.0</code></td><td>Image name and tag. The version is already filled in for the release the folder came from.</td></tr><tr><td><code>GATEWAY_URL</code></td><td><code>https://depgate.example.com</code></td><td>The address people and package clients use. Registry responses contain links built from it.</td></tr><tr><td><code>JWT_SECRET</code></td><td>output of <code>openssl rand -hex 32</code></td><td>Signs sessions and registry tokens. Keep it: a new value signs everyone out and invalidates every registry token.</td></tr><tr><td><code>ADMIN_EMAIL</code>, <code>ADMIN_PASSWORD</code></td><td><code>security-team@example.com</code></td><td>The first Security account, created on first start only. Change the password in the web interface afterwards; both variables may then be removed.</td></tr><tr><td><code>DB_HOST</code>, <code>DB_PORT</code>, <code>DB_USER</code>, <code>DB_PASSWORD</code>, <code>DB_NAME</code></td><td></td><td>PostgreSQL connection (app only).</td></tr><tr><td><code>DB_SSL</code>, <code>DB_SSL_CA_FILE</code></td><td><code>true</code>, <code>/certs/ca.crt</code></td><td>Encrypt the PostgreSQL connection and verify the server certificate (app only).</td></tr><tr><td><code>REDIS_URL</code></td><td><code>redis://:password@redis.example.com:6379</code></td><td>Redis connection (app only). Use <code>rediss://</code> for TLS.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_SIZE_GB</code></td><td><code>50</code></td><td>Disk the <a href="/depgate/admin/artifact-cache">artifact cache</a> may use. The cache is on in both setups.</td></tr></tbody></table><p>Email, the outbound proxy and every tuning option can also go in <code>.env</code>. See <a href="/depgate/reference/configuration">Configuration</a>. To write <code>.env</code> by hand instead of with the script: <code>cp .env.example .env &amp;&amp; chmod 600 .env</code>, then fill in the values.</p><h2 id="step-3-add-the-certificate" tabindex="-1">Step 3: Add the certificate <a class="header-anchor" href="#step-3-add-the-certificate" aria-label="Permalink to &quot;Step 3: Add the certificate&quot;">​</a></h2><p>DepGate serves HTTPS on port 443 and redirects port 80 to it. Put three files in the setup&#39;s <code>certs/</code> folder:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>tls.crt</code></td><td>The server certificate followed by its intermediate certificates (full chain), in PEM. It must name the host in <code>GATEWAY_URL</code>.</td></tr><tr><td><code>tls.key</code></td><td>The private key of <code>tls.crt</code>, in PEM, without a passphrase.</td></tr><tr><td><code>ca.crt</code></td><td>Your CA certificate (public). DepGate also trusts it for outgoing connections, such as internal registries.</td></tr></tbody></table><p>The container runs as user ID 1000, which must be able to read the files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certs/tls.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certs/ca.crt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 640</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certs/tls.key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certs/tls.key</span></span></code></pre></div><details class="details custom-block"><summary>No company CA yet?</summary><p><code>./2-generate-cert.sh depgate.example.com</code> creates a local CA (kept in the setup&#39;s <code>local-ca/</code>, never mounted into the container) and issues a certificate for the name. Every client must then trust <code>certs/ca.crt</code>.</p></details><p>To use your own TLS proxy or load balancer instead, set <code>DISABLE_SSL=true</code> (add it to the <code>1-configure.sh</code> line) and skip this step. See <a href="./https-and-networking#behind-your-own-tls-proxy">HTTPS and networking</a>.</p><h2 id="step-4-start-depgate" tabindex="-1">Step 4: Start DepGate <a class="header-anchor" href="#step-4-start-depgate" aria-label="Permalink to &quot;Step 4: Start DepGate&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./3-run.sh</span></span></code></pre></div><p>The script runs <code>docker compose up -d</code>, which pulls the image when it is missing, waits until the <code>app</code> service reports <code>(healthy)</code>, and checks HTTPS, the database, the web interface and the HTTP redirect. On first start DepGate creates its tables, the first Security account and the default repositories for every ecosystem, then begins downloading the malware feed and EPSS scores in the background.</p><p>The wait is up to 10 minutes: a database upgrade, or another DepGate instance starting on the same database, happens before the app listens. If it runs out, the script prints the log tail and exits with an error while the container keeps running; follow it with <code>./3-run.sh --logs</code>.</p><div class="tip custom-block"><p class="custom-block-title">One command</p><p><code>./quickstart.sh</code> runs the three scripts in order with defaults, for <code>https://localhost</code>. In <code>app-only/</code> it needs the same <code>DB_*</code> and <code>REDIS_URL</code> variables as <code>1-configure.sh</code>.</p></div><h2 id="step-5-verify" tabindex="-1">Step 5: Verify <a class="header-anchor" href="#step-5-verify" aria-label="Permalink to &quot;Step 5: Verify&quot;">​</a></h2><ol><li><strong>Health:</strong> <code>curl https://depgate.example.com/healthz</code> returns <code>{&quot;status&quot;:&quot;ok&quot;}</code>, and <code>/readyz</code> returns <code>{&quot;status&quot;:&quot;ready&quot;}</code> once PostgreSQL and Redis are reachable.</li><li><strong>Sign in:</strong> open <code>GATEWAY_URL</code> and sign in with <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code>. Change the password.</li><li><strong>Install a package:</strong> follow <a href="/depgate/developers/connect-package-managers">Connect your package manager</a> and install any package through DepGate. The Dashboard counts it.</li></ol><h2 id="after-installation" tabindex="-1">After installation <a class="header-anchor" href="#after-installation" aria-label="Permalink to &quot;After installation&quot;">​</a></h2><ul><li><a href="/depgate/admin/email">Set up email</a> so you can invite people.</li><li><a href="/depgate/admin/users">Add people</a> and give them the User or Security role.</li><li><a href="/depgate/admin/repositories">Add your internal registries</a>.</li><li><a href="/depgate/admin/create-policy">Create your first policies</a>, starting in <a href="/depgate/admin/monitoring">monitor mode</a>.</li><li>Plan <a href="./operations">operations and upgrades</a>.</li></ul>`,44)])])}const u=t(o,[["render",d]]);export{k as __pageData,u as default};
